INSERT INTO public.offer_products (id,name,category_id,description,unit,min_quantity,is_active,partner_portal_visible,base_price,price_net,price_gross,vat_rate,cost_price,cost_net,cost_gross,staff_cost,staff_cost_net,staff_cost_gross,setup_time_hours,teardown_time_hours,service_duration_hours,offer_short_description,offer_description,public_description,offer_compact_description,offer_page_variant,offer_page_enabled,sales_packages_enabled,tags,offer_benefits,offer_additional_requirements) SELECT id,name,category_id,description,unit,min_quantity,is_active,partner_portal_visible,base_price,price_net,price_gross,vat_rate,cost_price,cost_net,cost_gross,staff_cost,staff_cost_net,staff_cost_gross,setup_time_hours,teardown_time_hours,service_duration_hours,offer_short_description,offer_description,public_description,offer_compact_description,offer_page_variant,offer_page_enabled,sales_packages_enabled,tags,offer_benefits,offer_additional_requirements FROM jsonb_populate_record(NULL::public.offer_products,'{"id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Świat filmu i bajek — dekoracja sali", "category_id": "bbfd19cd-ab96-412f-8584-c45e3c07dd71", "description": "Produkt roboczy do indywidualnej wyceny. Modułowy wystrój imprezy pracowniczej dla dorosłych: wejście filmowe, strefa zdjęć, dekoracja światłem oraz opcjonalne dekoracje stołów, akcenty postaci i personalizacja. Zakres, ilości, projekt oraz koszty ustalamy przed aktywacją produktu i przygotowaniem oferty.", "unit": "aranżacja", "min_quantity": 1, "is_active": false, "partner_portal_visible": false, "base_price": 0, "price_net": null, "price_gross": null, "vat_rate": 23, "cost_price": null, "cost_net": null, "cost_gross": null, "staff_cost": null, "staff_cost_net": null, "staff_cost_gross": null, "setup_time_hours": null, "teardown_time_hours": null, "service_duration_hours": null, "offer_short_description": "Filmowy klimat imprezy dla dorosłych z motywami bajkowymi dobranymi do wydarzenia.", "offer_description": "Aranżacja sali na imprezę w temacie postaci z filmów i bajek. Bazę tworzą wejście w klimacie premiery, miejsce do zdjęć i dekoracja światłem. Zakres można rozszerzyć o dekoracje stołów, rekwizyty tematyczne i personalizowane oznaczenia. Wybrane elementy, ich ilości i projekt ustalamy dla konkretnej sali. Montaż, demontaż i logistykę uwzględniamy w indywidualnej wycenie.", "public_description": "Świat filmu i bajek — dekoracja imprezy dla dorosłych\n\nModułowa aranżacja sali na integrację pracowniczą lub bal przebierańców inspirowany postaciami z filmów i bajek. Proponujemy wspólną bazę filmową oraz wybrane akcenty tematyczne. Motywy i kolory dobieramy do charakteru imprezy, wnętrza oraz ustalonego budżetu.\n\nElementy do wyboru\nWejście w klimacie premiery filmowej z dywanem i słupkami; ścianka jako miejsce wspólnych zdjęć; statyczna dekoracja światłem przy wybranych ścianach; niskie dekoracje stołów; akcenty wybranych postaci i światów; personalizowane tablice oraz oznaczenia. Każdy z tych elementów można uwzględnić w uzgodnionym pakiecie. Nie wszystkie są automatycznie wliczone w zakres.\n\nBaza filmowa i motywy bajkowe\nDywan, tło do zdjęć i oświetlenie tworzą bazę aranżacji. Do niej można dobrać np. motyw przygodowy, baśniowy albo retro oraz rekwizyty pasujące do kostiumów gości. Konkretne postacie, grafiki, materiały i sposób wykonania zatwierdzamy przed produkcją. Nietypowe rekwizyty mogą wymagać wykonania, zakupu lub wynajmu; ich dostępność i cenę potwierdzamy osobno.\n\nDopasowanie do sali\nProponujemy dekoracje wolnostojące i światło ustawiane przy ścianach. Wysokość, szerokość i miejsca ustawienia wymagają dopasowania do rzeczywistej przestrzeni, drzwi, instalacji sufitowych oraz ciągów komunikacyjnych. Metraż sali sam w sobie nie określa liczby dekoracji. Liczbę punktów światła i dekoracji stołów dobieramy po otrzymaniu rzutu lub zdjęć oraz układu stołów.\n\nPrzygotowanie i realizacja\nUzgadniamy projekt, listę elementów, ich ilości oraz harmonogram montażu i demontażu. Elementy wymagające personalizacji przygotowujemy po zatwierdzeniu treści i projektu. Transport, dostęp do obiektu, godziny pracy ekipy i ewentualny demontaż nocny uwzględniamy w indywidualnej kalkulacji.\n\nWycena i zakres\nProdukt stanowi bazę do indywidualnej wyceny dekoracji. Końcowa oferta wskazuje wybrane elementy, ilości, zakres przygotowania oraz cenę. Strefa zdjęć oznacza dekoracyjne tło; fotograf, fotobudka, kostiumy, animatorzy, DJ, nagłośnienie i obsługa programu nie są automatycznie częścią dekoracji.\n\nDo przygotowania oferty potrzebujemy lokalizacji, terminu, godzin imprezy i dostępu technicznego, zdjęć lub rzutu sali, liczby i ustawienia stołów, wybranych motywów oraz orientacyjnego budżetu albo wskazania priorytetowych stref.", "offer_compact_description": null, "offer_page_variant": "default", "offer_page_enabled": false, "sales_packages_enabled": false, "tags": ["dekoracja sali", "film i bajki", "impreza pracownicza", "do wyceny"], "offer_benefits": ["Dobór elementów do budżetu i układu sali", "Filmowa baza i wybrane motywy bajkowe", "Możliwość zbudowania pakietu z kilku stref"], "offer_additional_requirements": [{"id": "16d5abe9-8d9c-488f-b5dc-dbac0d15e70f", "title": "ZDJĘCIA I RZUT SALI", "category": "place", "description": "Wymiary, wysokość, drzwi, instalacje sufitowe, przejścia oraz plan ustawienia stołów i parkietu."}, {"id": "cba035e2-6f53-4895-ae82-8d63335d698f", "title": "STOŁY I LICZBA GOŚCI", "category": "resources", "description": "Liczba, kształt i wymiary stołów oraz dostępne wyposażenie hotelu. Dekoracje stołów wyceniamy na podstawie ich liczby."}, {"id": "116fd24a-a53d-4048-ad0d-489a70f050df", "title": "WYBÓR MOTYWÓW", "category": "resources", "description": "Uzgodnij wybrane postacie lub światy, paletę kolorów, preferencje stylistyczne i treść personalizacji przed przygotowaniem elementów."}, {"id": "b878142f-4d31-4f22-9c1b-f511e65aa545", "title": "MONTAŻ I DEMONTAŻ", "category": "setup", "description": "Adres realizacji, dostęp do sali, okna montażu i demontażu, rozładunek, parking oraz możliwość przechowania opakowań."}, {"id": "5f4d7403-c1e4-47ef-a4d1-acf0cdd0dbaa", "title": "USTAWIENIE I ZASILANIE", "category": "place", "description": "Potwierdź dostęp do zasilania i miejsca ustawienia dekoracji. Podwieszenia oraz mocowania do ścian lub sufitu wymagają odrębnego uzgodnienia z obiektem."}]}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment) SELECT id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "4b429486-eff9-4a74-9396-41293008bf08", "product_id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Wejście filmowe", "short_description": "Dywan i słupki prowadzące gości w klimat premiery.", "description": "Do wyceny i potwierdzenia zakresu. Proponowany zakres: jeden dostępny czerwony dywan oraz cztery słupki hotelowe. Długość, stan dywanu, sposób połączenia słupków i ustawienie potwierdzamy przed wyceną. Nie zakładamy dekoracji całego korytarza. Personalizowana tablica stanowi osobny element.", "benefits": ["Dywan i cztery słupki jako punkt wyjścia", "Układ dopasowany do wejścia"], "price_net": 0, "price_gross": 0, "display_order": 0, "is_active": false, "partner_portal_visible": false, "is_recommended": false, "overrides_equipment": true}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment) SELECT id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "fd24e51f-3bd7-45dd-8f5e-3c9e9e233b40", "product_id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Strefa zdjęć", "short_description": "Wolnostojące tło do zdjęć grupowych i kostiumów gości.", "description": "Do wyceny i potwierdzenia zakresu. Baza: jedna ścianka dekoracyjna z magazynu. Motyw, poszycie, szerokość i rzeczywistą wysokość konstrukcji sprawdzamy przed wyborem do sali. Dla wysokości sali 3 m projektujemy wolnostojący układ z zapasem do sufitu i instalacji. Dopasowanie tła do motywu filmowo-bajkowego oraz ewentualne nowe wydruki wymagają osobnej kalkulacji. Element obejmuje scenografię, bez fotografa i fotobudki.", "benefits": ["Jedno główne miejsce wspólnych zdjęć", "Tło dopasowywane do tematu"], "price_net": 0, "price_gross": 0, "display_order": 1, "is_active": false, "partner_portal_visible": false, "is_recommended": false, "overrides_equipment": true}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment) SELECT id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "1d9190fb-21a4-44a3-ba44-b0761300577d", "product_id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Dekoracja światłem", "short_description": "Kolor na wybranych ścianach i w strefach dekoracji.", "description": "Do wyceny i potwierdzenia zakresu. Punkt wyjścia do projektu: 20 reflektorów LED PAR w jednej uzgodnionej palecie, pracujących statycznie. Liczbę i miejsca ustawienia potwierdzamy po poznaniu rzutu, koloru ścian i dostępnego zasilania. To propozycja konfiguracji, a nie gwarancja równomiernego oświetlenia całych 360 m². Światło parkietu, sceny i zmiany prowadzone przez realizatora wymagają odrębnego zakresu.", "benefits": ["Statyczna paleta dopasowana do motywu", "Podkreślenie wybranych stref sali"], "price_net": 0, "price_gross": 0, "display_order": 2, "is_active": false, "partner_portal_visible": false, "is_recommended": false, "overrides_equipment": true}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment) SELECT id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "b4bba897-2bc5-4a97-9892-f9aa584b15d0", "product_id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Dekoracje stołów", "short_description": "Niskie akcenty tematyczne dobrane do liczby stołów.", "description": "Do wyceny i potwierdzenia zakresu. Opcjonalne kompozycje i oznaczenia z motywami filmu lub bajek. Projektujemy niskie formy, aby umożliwić rozmowę przy stole. Ilość, materiały i cena zależą od liczby oraz kształtu stołów; nie przyjmujemy ich na podstawie samej liczby 90–100 gości. Obrusy, zastawa, kwiaty i świece wymagają wskazania w uzgodnionym zakresie. Elementy do zaprojektowania i skalkulowania.", "benefits": ["Wspólny motyw przy stołach", "Rozliczenie według uzgodnionej liczby kompozycji"], "price_net": 0, "price_gross": 0, "display_order": 3, "is_active": false, "partner_portal_visible": false, "is_recommended": false, "overrides_equipment": true}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment) SELECT id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "30b22edc-84fb-4b2d-830c-e61a0b2ff64c", "product_id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Postacie i rekwizyty tematyczne", "short_description": "Wybrane światy filmowe i bajkowe jako akcenty scenografii.", "description": "Do wyceny i potwierdzenia zakresu. Opcjonalne rekwizyty, sylwetki lub grafiki odnoszące się do uzgodnionych postaci i światów. Dla imprezy pracowniczej proponujemy akcenty dopasowane do kostiumów gości, np. przygodowe, baśniowe lub retro. Projekt, liczbę, wymiary i materiały zatwierdzamy przed wykonaniem. Konkretne postacie ani rekwizyty nie są potwierdzone jako wyposażenie magazynu; wykonanie, zakup lub wynajem wymagają ustalenia kosztu i terminu. Element nie obejmuje kostiumów ani animatorów.", "benefits": ["Możliwość wyboru motywów przez klienta", "Akcenty uzupełniające filmową bazę"], "price_net": 0, "price_gross": 0, "display_order": 4, "is_active": false, "partner_portal_visible": false, "is_recommended": false, "overrides_equipment": true}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment) SELECT id,product_id,name,short_description,description,benefits,price_net,price_gross,display_order,is_active,partner_portal_visible,is_recommended,overrides_equipment FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "48fb7e93-654e-4b32-af69-0a309f70d8cb", "product_id": "afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf", "name": "Personalizowane oznaczenia", "short_description": "Tablica powitalna, nazwa imprezy i oznaczenia stref.", "description": "Do wyceny i potwierdzenia zakresu. Opcjonalny projekt oraz wykonanie uzgodnionych tablic lub wydruków. Zakres ustalamy według liczby, formatów, materiałów i treści. Organizator przekazuje właściwe logotypy, nazwę wydarzenia i teksty; projekt trafia do zatwierdzenia przed produkcją. Mocowania i stojaki należy uwzględnić w kalkulacji. Personalizacja ścianki i tablic powitalnych jest liczona tylko raz w uzgodnionym pakiecie.", "benefits": ["Własna nazwa wydarzenia i treści", "Spójne oznaczenie wybranych stref"], "price_net": 0, "price_gross": 0, "display_order": 5, "is_active": false, "partner_portal_visible": false, "is_recommended": false, "overrides_equipment": true}'::jsonb);
